// Stepper — a four-wire motor turned by its own sequence.
//
// The class library energises two coils at a time in a repeating order; the
// shaft moves one step for each change. 200 steps make a full turn.

#include <Stepper.h>

const int STEPS_PER_REV = 200;
Stepper motor(STEPS_PER_REV, 8, 9, 10, 11);

void setup() {
  motor.setSpeed(30);
}

void loop() {
  motor.step(STEPS_PER_REV / 4);
  delay(500);
}
